  [1253380] = { "Aumenta i tuoi danni magici di $N1 e le tue cure di $N2 quando hai equipaggiato un bastone o una bacchetta.", "I tuoi danni magici aumentano di $N1 e il tuo bonus alla guarigione di $N2 mentre hai equipaggiato un bastone o una bacchetta.", 0x503a7f57, 0x08c78d60, "uu" },
  [1253381] = { "I tuoi incantesimi di cura hanno una probabilità di scagliare verso il bersaglio una bolla di melma che dura $D1 e gli permette di assorbire fino a $N2 danni.", "I tuoi incantesimi di cura hanno una probabilità di scagliare una bolla di melma verso il bersaglio per $D1, permettendogli di assorbire fino a $N2 danni.", 0xecf68dd6, 0xd8ccda8e, "uu" },
