  [1253388] = { "Aumenta la tua potenza d'attacco di $N1 quando impugni un'arma contundente.", "Potenza d'attacco aumentata di $N1 quando impugni un'arma contundente.", 0xd0197719, 0xafd2bd19, "uu" },
  [1253389] = { "I tuoi attacchi in mischia hanno una probabilità di rivelare un punto debole nelle difese dell'avversario, riducendone l'Armatura di $N1 per $D1.", "I tuoi attacchi in mischia hanno una probabilità di rivelare un punto debole nelle difese dell'avversario, riducendone l'Armatura di $N1 per $D1.", 0x8e56ad8c, 0x95c5e85f, "uu" },
  [1253393] = { "I tuoi incantesimi di cura hanno una probabilità di scagliare verso il bersaglio una bolla di melma che dura $D1 e gli permette di assorbire fino a $N2 danni.", "Assorbe $N1 danni.", 0xb88521ae, 0xe074129a, "uu" },
  [1253404] = { "I tuoi attacchi in mischia hanno una probabilità di rivelare un punto debole nelle difese dell'avversario, riducendone l'Armatura di $N1 per $D1.", "Un punto debole nelle tue difese ha ridotto la tua Armatura di $N1.", 0xb88521b6, 0x8f0ae9bb, "uu" },
  [1253456] = { "Sputa melma intorno a te, colpendo i bersagli con un muco che sopprime la mente.\n\nQuando l'effetto termina, i bersagli colpiti rilasciano una Nova di Melma che infligge $N1 danni da natura agli alleati vicini.", nil, 0x0a516fd9, nil, "um" },
  [1253463] = { "Sputa melma intorno a te, colpendo i bersagli con un muco che sopprime la mente.\n\nQuando l'effetto termina, i bersagli colpiti rilasciano una Nova di Melma che infligge $N1 danni da natura agli alleati vicini.", "La tua coscienza è stata soppressa.", 0xb8856333, 0xa02d0033, "uu" },
  [1253478] = { "Divora creature e avventurieri vivi controllati dalla melma, curandoti del $N1% della salute massima per ogni vittima consumata.", nil, 0x6e0f9f4d, nil, "um" },
  [1253480] = { "Divora creature e avventurieri vivi controllati dalla melma, ottenendo uno scudo che assorbe danni pari al $N1% della salute massima per ogni vittima consumata. Dura $D1.", "Assorbe fino a $N1 danni.", 0x2441bab6, 0x37b5767b, "uu" },
  [1253487] = { "Cospargi il mostro bersaglio con una pestilenza sperimentale, impedendo in modo permanente la maggior parte delle fonti di rigenerazione della salute.\n\nUtilizzabile solo su The Horror, Revildesh e la Metamorphic Fury.", "La maggior parte delle fonti di rigenerazione della salute è soppressa in modo permanente.", 0x7cb8ca2e, 0x836f5a85, "uu" },
  [1253552] = { "Spara veleno contro un nemico, infliggendo $N1 danni da natura e poi altri danni ogni $D1 per $D2.", "$N1 danni da natura inflitti ogni $D1.", 0xb5026299, 0xd008869e, "uu" },
  [1253568] = { "Rigenera $N1 salute a tutti i membri del gruppo vicini ogni $D1 per $D2. Il Druido deve canalizzare per mantenere l'incantesimo.", "$N1 salute rigenerata ogni $D1 ai membri del gruppo vicini.", 0x1216d9a1, 0x793ba8c5, "uu" },
  [1253636] = { "Quando The Horror lancia Coagulo o Coagulazione, infligge danni pari al $N1% della salute massima del giocatore colpito.\n\nI bersagli che non sono giocatori vengono uccisi all'istante.", nil, 0x6a717d14, nil, "um" },
  [1253665] = { "Sputa melma intorno a te, colpendo i bersagli con un muco che sopprime la mente.\n\nQuando l'effetto termina, i bersagli colpiti rilasciano una Nova di Melma che infligge $N1 danni da natura agli alleati vicini.", nil, 0xb8856333, nil, "um" },
  [1253722] = { "Le stelle cadono dall'alto, infliggendo $N1 danni.", nil, 0xe0cf85f6, nil, "um" },
  [1253743] = { "Fissa un giocatore a caso e lo insegue finché la tua soglia d'attenzione lo consente o per $D1, a seconda di quale dei due è più breve.", nil, 0x854e51e8, nil, "um" },
  [1253746] = { "Fissa un giocatore a caso e lo insegue finché la tua soglia d'attenzione lo consente o per $D1, a seconda di quale dei due è più breve.", "Un enorme dinosauro affamato ti sta inseguendo!\n\nL'adrenalina ti scorre nelle vene. La tua velocità di movimento aumenta del $N1% e sei immune al suo Terrorizing Roar.", 0xb8862bc8, 0x226608e1, "uu" },
  [1253774] = { "Sprigiona uno stridio che infligge $N1 danni fisici e silenzia i bersagli colpiti per $D1.", "Silenziato.", 0xb42f59ee, 0x20816e34, "uu" },
  [1253780] = { { "Divora il pasto che hai come bersaglio, infliggendo danni pari al $N1% della sua salute massima e stordendolo per $D1.\n\nTi curi del $N3% della tua salute massima ogni volta che divori con successo un bersaglio.", "Divora il pasto che hai come bersaglio, uccidendolo all'istante.\n\nTi curi del $N1% della tua salute massima ogni volta che divori con successo un bersaglio.", shape = { "3/1", "1/0" } }, nil, 0xa7be7302, nil, "um" },
  [1253789] = { { "Divora il pasto che hai come bersaglio, infliggendo danni pari al $N1% della sua salute massima e stordendolo per $D1.\n\nTi curi del $N3% della tua salute massima ogni volta che divori con successo un bersaglio.", "Divora il pasto che hai come bersaglio, uccidendolo all'istante.\n\nTi curi del $N1% della tua salute massima ogni volta che divori con successo un bersaglio.", shape = { "3/1", "1/0" } }, "Ti hanno divorato in parte! Stordito.", 0xb8862dd1, 0xf187fb71, "uu" },
  [1253790] = { { "Divora il pasto che hai come bersaglio, infliggendo danni pari al $N1% della sua salute massima e stordendolo per $D1.\n\nTi curi del $N3% della tua salute massima ogni volta che divori con successo un bersaglio.", "Divora il pasto che hai come bersaglio, uccidendolo all'istante.\n\nTi curi del $N1% della tua salute massima ogni volta che divori con successo un bersaglio.", shape = { "3/1", "1/0" } }, "Ti hanno divorato!", 0xb8862dd1, 0xf5a4f322, "uu" },
  [1253815] = { "Sprigiona un Terrorizing Roar che incute terrore nel cuore delle prede vicine per $D1.", "Fuga in preda al terrore.", 0xe54461cf, 0xfa67e4a8, "uu" },
  [1253833] = { "La spessa pelle del gigantosauro riduce tutti i danni subiti del $N1%.\n\nLe fosse di spuntoni possono penetrarla, rimuovendo temporaneamente questo effetto finché la ferita non guarisce.", "Tutti i danni subiti ridotti del $N1%.\n\nLe fosse chiodate possono penetrare questa difesa per breve tempo.", 0x0af01e6f, 0x871409ea, "uu" },
  [1253843] = { "Una recente passeggiata tra gli spuntoni ha causato una ferita dolorosa, che infligge $N1 danni fisici per accumulo ogni $D1. Quando infligge danni, viene rimosso un accumulo.\n\nFinché sei sotto questo effetto, non puoi beneficiare di Devilsaur Hide.", "Sanguini e subisci $N1 danni ogni $D1. Non puoi beneficiare di Devilsaur Hide.", 0x392f29cf, 0xd919a3b6, "uu" },
  [1253931] = { nil, "Velocità di movimento ridotta.", nil, 0xeadcb05a, "mu" },
  [1253966] = { "Scatena la tua furia ogni $D1, infliggendo $N2 danni da fuoco ai patetici deboli entro $N3 m e aumentando i danni da fuoco che subiscono del $N4% per $D2. Si accumula fino a $N6 volte.", "Danni da fuoco subiti aumentati del $N1%.", 0x1d013dc5, 0x7326be27, "uu" },
